//! The acceptance checks of the quadratic rough Heston calibration (#967).
//!
//! The surface the fit recovers is generated by the model itself on the same grid and seed, so
//! the objective is zero at the true parameters up to the implied volatility solver's
//! tolerance, and the check is on the search, not on Monte Carlo noise. No parameter set here
//! comes from either paper: all are illustrative.

use optionstratlib_core::model::Positive;
use optionstratlib_core::model::decimal::decimal_to_f64;
use optionstratlib_core::model::types::OptionStyle;
use optionstratlib_core::pos_or_panic;
use optionstratlib_simulation::error::QuadraticRoughHestonError;
use optionstratlib_simulation::simulation::{
    QuadraticRoughHestonCalibrationConfig, QuadraticRoughHestonFreeParameters,
    QuadraticRoughHestonGrid, QuadraticRoughHestonKernel, QuadraticRoughHestonMonteCarloConfig,
    QuadraticRoughHestonParams, QuadraticRoughHestonQuote, QuadraticRoughHestonSurfacePoint,
    calibrate_quadratic_rough_heston, price_surface_quadratic_rough_heston,
    price_vanilla_quadratic_rough_heston,
};
use rust_decimal::Decimal;
use rust_decimal_macros::dec;
use std::num::{NonZeroU64, NonZeroUsize};

const SEED: u64 = 967;

fn kernel() -> QuadraticRoughHestonKernel {
    QuadraticRoughHestonKernel::try_new(dec!(0.6), 2, dec!(5)).unwrap()
}

fn params(
    a: Decimal,
    b: Decimal,
    c: Decimal,
    lambda: Decimal,
    eta: Decimal,
    initial: [Decimal; 2],
) -> QuadraticRoughHestonParams {
    QuadraticRoughHestonParams::try_new(
        a,
        b,
        c,
        lambda,
        eta,
        kernel(),
        initial.to_vec(),
        Positive::HUNDRED,
    )
    .unwrap()
}

/// The parameters the surface is generated from.
fn truth() -> QuadraticRoughHestonParams {
    params(
        dec!(0.4),
        dec!(0.1),
        dec!(0.02),
        dec!(1.5),
        dec!(0.8),
        [dec!(-0.1), dec!(-0.2)],
    )
}

/// Three maturities and five strikes.
fn points() -> Vec<QuadraticRoughHestonSurfacePoint> {
    let mut points = Vec::new();
    for maturity in [0.1, 0.25, 0.5] {
        for strike in [85.0, 95.0, 100.0, 105.0, 115.0] {
            points.push(QuadraticRoughHestonSurfacePoint {
                maturity: Positive::new(maturity).unwrap(),
                strike: Positive::new(strike).unwrap(),
            });
        }
    }
    points
}

fn monte_carlo() -> QuadraticRoughHestonMonteCarloConfig {
    QuadraticRoughHestonMonteCarloConfig {
        paths: NonZeroUsize::new(2_000).unwrap(),
        max_step: pos_or_panic!(0.01),
        seed: SEED,
    }
}

/// The model's surface at the truth, as quotes of weight one.
fn quotes() -> Vec<QuadraticRoughHestonQuote> {
    price_surface_quadratic_rough_heston(&truth(), &points(), &monte_carlo())
        .unwrap()
        .into_iter()
        .map(|quote| QuadraticRoughHestonQuote {
            maturity: quote.maturity,
            strike: quote.strike,
            implied_volatility: quote.implied_volatility.unwrap(),
            weight: Positive::ONE,
        })
        .collect()
}

fn as_f64(value: Decimal) -> f64 {
    decimal_to_f64(value).unwrap()
}

fn relative_error(actual: Decimal, expected: Decimal) -> f64 {
    (as_f64(actual) - as_f64(expected)).abs() / as_f64(expected).abs()
}

/// Every point of the surface prices as its out-of-the-money vanilla on the same paths as the
/// single-maturity pricer at a grid of the same step, and its implied volatility inverts the
/// price.
#[test]
fn test_price_surface_matches_the_vanilla_pricer_and_inverts_its_prices() {
    let model = truth();
    let surface = price_surface_quadratic_rough_heston(&model, &points(), &monte_carlo()).unwrap();
    assert_eq!(surface.len(), 15);
    for quote in &surface {
        let expected_style = if quote.strike >= Positive::HUNDRED {
            OptionStyle::Call
        } else {
            OptionStyle::Put
        };
        assert_eq!(quote.style, expected_style);
        assert!(quote.price > Decimal::ZERO, "{quote:?}");
        assert!(quote.standard_error > Decimal::ZERO, "{quote:?}");
        let volatility = quote.implied_volatility.expect("a price inside the band");
        assert!(volatility > dec!(0.05) && volatility < dec!(1), "{quote:?}");
    }
    // The first maturity is one segment of the schedule, so its points sit on the paths of
    // the single-maturity pricer with the same number of steps.
    let grid = QuadraticRoughHestonGrid::try_new(dec!(0.1), 10).unwrap();
    for quote in surface
        .iter()
        .filter(|quote| quote.maturity == pos_or_panic!(0.1))
    {
        let single = price_vanilla_quadratic_rough_heston(
            &model,
            &grid,
            quote.style,
            quote.strike,
            NonZeroUsize::new(2_000).unwrap(),
            SEED,
        )
        .unwrap();
        assert!(
            (single.price() - quote.price).abs() < dec!(1e-9),
            "{} against {}",
            single.price(),
            quote.price
        );
    }
}

/// The fit recovers `(a, b, c, lambda, eta)` from the model's own surface, with the initial
/// factors fixed, from a start 30% to 50% away on each parameter. The objective is zero at the
/// truth up to the implied volatility solver's tolerance, so the recovered parameters sit
/// within `RELATIVE_TOLERANCE` of it. Measured: every parameter within `1e-6` relative, an
/// RMSE of `5e-10`, in 563 iterations and 903 evaluations of 2,000 paths.
#[test]
fn test_calibration_recovers_the_model_parameters_from_its_own_surface() {
    const RELATIVE_TOLERANCE: f64 = 1e-3;
    let start = params(
        dec!(0.6),
        dec!(0.05),
        dec!(0.012),
        dec!(1.0),
        dec!(1.1),
        [dec!(-0.1), dec!(-0.2)],
    );
    let config = QuadraticRoughHestonCalibrationConfig {
        monte_carlo: monte_carlo(),
        max_iterations: NonZeroU64::new(4_000).unwrap(),
        tolerance: pos_or_panic!(1e-6),
        initial_step: pos_or_panic!(0.1),
    };
    let fit = calibrate_quadratic_rough_heston(
        &quotes(),
        &start,
        QuadraticRoughHestonFreeParameters::MODEL,
        &config,
    )
    .unwrap();

    let truth = truth();
    let fitted = fit.params();
    assert!(
        fit.rmse().to_dec() < dec!(1e-5),
        "rmse {} after {} iterations and {} evaluations",
        fit.rmse(),
        fit.iterations(),
        fit.evaluations()
    );
    for (name, actual, expected) in [
        ("a", fitted.a(), truth.a()),
        ("b", fitted.b(), truth.b()),
        ("c", fitted.c(), truth.c()),
        ("lambda", fitted.lambda(), truth.lambda()),
        ("eta", fitted.eta(), truth.eta()),
    ] {
        assert!(
            relative_error(actual, expected) < RELATIVE_TOLERANCE,
            "{name}: {actual} against {expected}, rmse {}, {} iterations",
            fit.rmse(),
            fit.iterations()
        );
    }
    assert_eq!(fitted.initial_factors(), truth.initial_factors());
    assert_eq!(fitted.kernel(), truth.kernel());
    assert_eq!(fitted.spot(), truth.spot());
    assert!(
        relative_error(fitted.initial_variance(), truth.initial_variance()) < RELATIVE_TOLERANCE
    );

    // The report: seed, paths and grid, and one fit per quote with its residual.
    assert_eq!(fit.seed(), SEED);
    assert_eq!(fit.paths(), 2_000);
    let steps: Vec<usize> = fit.grid().iter().map(|segment| segment.steps).collect();
    assert_eq!(steps, vec![10, 15, 25]);
    assert_eq!(fit.quotes().len(), 15);
    for quote_fit in fit.quotes() {
        assert!(quote_fit.residual.abs() < dec!(1e-4), "{quote_fit:?}");
        let error = quote_fit
            .implied_volatility_error
            .expect("a model price inside the band");
        assert!(error.abs() < dec!(1e-4), "{quote_fit:?}");
        assert!(quote_fit.vega > Decimal::ZERO);
        assert!(quote_fit.model_standard_error > Decimal::ZERO);
    }
    assert!(fit.objective() >= Decimal::ZERO);
    assert!(fit.evaluations() > fit.iterations());
}

/// A fit of `a` and `c` alone, from the truth, converges at once: the objective is already
/// zero to the solver's tolerance.
#[test]
fn test_calibration_from_the_truth_stays_at_the_truth() {
    let config = QuadraticRoughHestonCalibrationConfig {
        monte_carlo: monte_carlo(),
        ..Default::default()
    };
    let free = QuadraticRoughHestonFreeParameters {
        a: true,
        c: true,
        ..Default::default()
    };
    let fit = calibrate_quadratic_rough_heston(&quotes(), &truth(), free, &config).unwrap();
    assert!(fit.rmse().to_dec() < dec!(1e-6), "{}", fit.rmse());
    assert!(relative_error(fit.params().a(), truth().a()) < 1e-3);
    assert!(relative_error(fit.params().c(), truth().c()) < 1e-3);
    assert_eq!(fit.params().b(), truth().b());
}

/// A quote of zero weight is reported but does not move the fit.
#[test]
fn test_calibration_zero_weight_quotes_are_reported_and_not_fitted() {
    let mut quotes = quotes();
    // Spoil one quote and give it no weight.
    quotes[7].implied_volatility = pos_or_panic!(0.9);
    quotes[7].weight = Positive::ZERO;
    let config = QuadraticRoughHestonCalibrationConfig {
        monte_carlo: monte_carlo(),
        ..Default::default()
    };
    let free = QuadraticRoughHestonFreeParameters {
        a: true,
        ..Default::default()
    };
    let fit = calibrate_quadratic_rough_heston(&quotes, &truth(), free, &config).unwrap();
    assert!(fit.rmse().to_dec() < dec!(1e-6), "{}", fit.rmse());
    let spoiled = &fit.quotes()[7];
    assert_eq!(spoiled.quote.weight, Positive::ZERO);
    assert!(spoiled.residual.abs() > dec!(0.1), "{spoiled:?}");
}

#[test]
fn test_calibration_invalid_inputs_return_typed_errors() {
    let config = QuadraticRoughHestonCalibrationConfig {
        monte_carlo: monte_carlo(),
        ..Default::default()
    };
    let quotes = quotes();
    let free = QuadraticRoughHestonFreeParameters::MODEL;

    let unweighted: Vec<_> = quotes
        .iter()
        .map(|quote| QuadraticRoughHestonQuote {
            weight: Positive::ZERO,
            ..*quote
        })
        .collect();
    assert!(matches!(
        calibrate_quadratic_rough_heston(&unweighted, &truth(), free, &config),
        Err(QuadraticRoughHestonError::NoQuotes)
    ));
    assert!(matches!(
        calibrate_quadratic_rough_heston(&[], &truth(), free, &config),
        Err(QuadraticRoughHestonError::NoQuotes)
    ));
    assert!(matches!(
        calibrate_quadratic_rough_heston(
            &quotes,
            &truth(),
            QuadraticRoughHestonFreeParameters::default(),
            &config
        ),
        Err(QuadraticRoughHestonError::NoFreeParameters)
    ));

    let mut zero_strike = quotes.clone();
    zero_strike[3].strike = Positive::ZERO;
    assert!(matches!(
        calibrate_quadratic_rough_heston(&zero_strike, &truth(), free, &config),
        Err(QuadraticRoughHestonError::InvalidQuote {
            index: 3,
            reason: "the strike must be positive"
        })
    ));
    let mut zero_maturity = quotes.clone();
    zero_maturity[0].maturity = Positive::ZERO;
    assert!(matches!(
        calibrate_quadratic_rough_heston(&zero_maturity, &truth(), free, &config),
        Err(QuadraticRoughHestonError::InvalidQuote { index: 0, .. })
    ));
    let mut zero_volatility = quotes.clone();
    zero_volatility[5].implied_volatility = Positive::ZERO;
    assert!(matches!(
        calibrate_quadratic_rough_heston(&zero_volatility, &truth(), free, &config),
        Err(QuadraticRoughHestonError::InvalidQuote {
            index: 5,
            reason: "the implied volatility must be positive"
        })
    ));

    for (parameter, bad) in [
        (
            "tolerance",
            QuadraticRoughHestonCalibrationConfig {
                tolerance: Positive::ZERO,
                ..config
            },
        ),
        (
            "initial_step",
            QuadraticRoughHestonCalibrationConfig {
                initial_step: Positive::ZERO,
                ..config
            },
        ),
        (
            "max_step",
            QuadraticRoughHestonCalibrationConfig {
                monte_carlo: QuadraticRoughHestonMonteCarloConfig {
                    max_step: Positive::ZERO,
                    ..config.monte_carlo
                },
                ..config
            },
        ),
        (
            "paths",
            QuadraticRoughHestonCalibrationConfig {
                monte_carlo: QuadraticRoughHestonMonteCarloConfig {
                    paths: NonZeroUsize::MIN,
                    ..config.monte_carlo
                },
                ..config
            },
        ),
    ] {
        let result = calibrate_quadratic_rough_heston(&quotes, &truth(), free, &bad);
        assert!(
            matches!(
                result,
                Err(QuadraticRoughHestonError::InvalidParameter { parameter: rejected, .. })
                    if rejected == parameter
            ),
            "{parameter}: {result:?}"
        );
    }
}

/// A free `a` cannot start at zero: it is searched as a logarithm. Fixed, it may.
#[test]
fn test_calibration_free_a_at_zero_returns_typed_error() {
    let flat = params(
        Decimal::ZERO,
        dec!(0.1),
        dec!(0.04),
        dec!(1.5),
        dec!(1),
        [dec!(-0.1), dec!(-0.2)],
    );
    let config = QuadraticRoughHestonCalibrationConfig {
        monte_carlo: monte_carlo(),
        ..Default::default()
    };
    assert!(matches!(
        calibrate_quadratic_rough_heston(
            &quotes(),
            &flat,
            QuadraticRoughHestonFreeParameters::MODEL,
            &config
        ),
        Err(QuadraticRoughHestonError::InvalidParameter { parameter: "a", .. })
    ));
    let without_a = QuadraticRoughHestonFreeParameters {
        a: false,
        ..QuadraticRoughHestonFreeParameters::MODEL
    };
    let config = QuadraticRoughHestonCalibrationConfig {
        max_iterations: NonZeroU64::new(5).unwrap(),
        ..config
    };
    assert!(matches!(
        calibrate_quadratic_rough_heston(&quotes(), &flat, without_a, &config),
        Err(QuadraticRoughHestonError::NoConvergence { iterations: 5 })
    ));
}

/// One iteration is not enough from a start away from the truth.
#[test]
fn test_calibration_iteration_limit_returns_typed_error() {
    let start = params(
        dec!(0.6),
        dec!(0.05),
        dec!(0.012),
        dec!(1.0),
        dec!(1.1),
        [dec!(-0.1), dec!(-0.2)],
    );
    let config = QuadraticRoughHestonCalibrationConfig {
        monte_carlo: monte_carlo(),
        max_iterations: NonZeroU64::MIN,
        ..Default::default()
    };
    assert!(matches!(
        calibrate_quadratic_rough_heston(
            &quotes(),
            &start,
            QuadraticRoughHestonFreeParameters::MODEL,
            &config
        ),
        Err(QuadraticRoughHestonError::NoConvergence { iterations: 1 })
    ));
}

/// A start whose paths explode is reported as the error of the path, and a surface with a
/// point off the grid is impossible by construction: every maturity defines a segment.
#[test]
fn test_calibration_exploding_start_returns_the_path_error() {
    let exploding = params(
        dec!(10000000000),
        Decimal::ZERO,
        dec!(1),
        dec!(1),
        dec!(10000000000),
        [Decimal::ZERO; 2],
    );
    let config = QuadraticRoughHestonCalibrationConfig {
        monte_carlo: monte_carlo(),
        ..Default::default()
    };
    assert!(matches!(
        calibrate_quadratic_rough_heston(
            &quotes(),
            &exploding,
            QuadraticRoughHestonFreeParameters::MODEL,
            &config
        ),
        Err(QuadraticRoughHestonError::NonFinite { .. })
    ));
    assert!(matches!(
        price_surface_quadratic_rough_heston(&exploding, &points(), &monte_carlo()),
        Err(QuadraticRoughHestonError::NonFinite { .. })
    ));
    assert!(matches!(
        price_surface_quadratic_rough_heston(&truth(), &[], &monte_carlo()),
        Err(QuadraticRoughHestonError::NoQuotes)
    ));
}
